const CornerBracket: React.FC<{
  x: number;
  y: number;
  flipX?: boolean;
  flipY?: boolean;
  opacity: number;
}> = ({x, y, flipX = false, flipY = false, opacity}) => (
  <g
    transform={`translate(${x} ${y}) scale(${flipX ? -1 : 1} ${flipY ? -1 : 1})`}
    opacity={opacity}
  >
    <path
      d="M0 44V12Q0 0 12 0H74"
      fill="none"
      stroke="#00d8ef"
      strokeWidth="3"
      strokeLinecap="square"
      filter="url(#cyan-glow)"
    />
    <path
      d="M9 39V17Q9 9 17 9H44"
      fill="none"
      stroke="#7ff8ff"
      strokeWidth="1"
      opacity=".48"
    />
    <circle cx="74" cy="0" r="3" fill="#8ffaff" />
  </g>
);

const RiskNode: React.FC<{
  x: number;
  y: number;
  index: number;
  frame: number;
  start: number;
  mapVisibility: number;
}> = ({x, y, index, frame, start, mapVisibility}) => {
  const nodeIn = progress(frame, start, start + 34, easeOut);
  const nodeOut = 1 - progress(frame, 758 - index * 22, 826 - index * 22);
  const visibility = nodeIn * nodeOut * mapVisibility;
  const cycle = Math.max(0, frame - start) % 92;
  const pulse = progress(cycle, 0, 92, Easing.linear);
  const flicker = 0.78 + Math.sin(frame / 8 + index * 1.7) * 0.18;

  return (
    <g
      transform={`translate(${x} ${y}) scale(${0.72 + nodeIn * 0.28})`}
      opacity={visibility}
      filter="url(#red-soft-glow)"
    >
      <circle
        r={19 + pulse * 17}
        fill="none"
        stroke="#ff234f"
        strokeWidth={1.5 - pulse * 0.7}
        opacity={(1 - pulse) * 0.78}
      />
      <circle r="16" fill="#150815" stroke="#ff3159" strokeWidth="2" />
      <circle r="11" fill="#300613" stroke="#ff6c83" strokeWidth="1" />
      <path
        d="M-5 -5L5 5M5 -5L-5 5"
        stroke="#fff4f6"
        strokeWidth="2.5"
        strokeLinecap="round"
        opacity={flicker}
      />
      <circle r="3" fill="#ffffff" opacity={flicker} />
    </g>
  );
};

const Atmosphere: React.FC<{
  frame: number;
  intensity: number;
}> = ({frame, intensity}) => {
  const specks = Array.from({length: 48}, (_, index) => {
    const x = 35 + seeded(index + 4) * 1850;
    const baseY = seeded(index + 84) * 1080;
    const speed = 0.17 + seeded(index + 143) * 0.38;
    const y = (baseY + frame * speed) % 1080;
    const opacity =
      (0.06 + seeded(index + 211) * 0.18) *
      (0.72 + Math.sin(frame / 18 + index) * 0.28);
    return (
      <line
        key={index}
        x1={x}
        x2={x}
        y1={y}
        y2={y + 8 + seeded(index + 330) * 24}
        stroke={index % 5 === 0 ? "#ff294d" : "#02a8bf"}
        strokeWidth={index % 5 === 0 ? 1.2 : 0.8}
        opacity={opacity * intensity}
      />
    );
  });

  return (
    <AbsoluteFill>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(ellipse at 50% 34%, rgba(1,42,51,.56), transparent 53%), radial-gradient(ellipse at 53% 87%, rgba(113,0,18,.29), transparent 42%), linear-gradient(180deg,#010507 0%,#02080b 48%,#050407 100%)",
        }}
      />
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: 0.42,
          backgroundImage:
            "linear-gradient(rgba(0,173,193,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(0,173,193,.035) 1px,transparent 1px)",
          backgroundSize: "44px 44px",
          maskImage:
            "linear-gradient(to bottom,transparent 3%,black 20%,black 88%,transparent 100%)",
        }}
      />
      <svg width="1920" height="1080" style={{position: "absolute", inset: 0}}>
        {specks}
      </svg>
      <div
        style={{
          position: "absolute",
          left: 125,
          right: 125,
          bottom: 66,
          height: 170,
          background:
            "radial-gradient(ellipse at center,rgba(255,23,61,.13),transparent 68%)",
          filter: "blur(26px)",
          opacity: intensity,
        }}
      />
    </AbsoluteFill>
  );
};

const RealWorldMap: React.FC<{
  frame: number;
  visibility: number;
  reveal: number;
}> = ({frame, visibility, reveal}) => {
  const scanCycle = (Math.max(0, frame - 80) % 260) / 260;
  const scanX = 240 + scanCycle * 1440;
  const breathing = 0.88 + Math.sin(frame / 32) * 0.12;

  return (
    <svg
      width="1920"
      height="1080"
      viewBox="0 0 1920 1080"
      style={{position: "absolute", inset: 0, opacity: visibility}}
      aria-hidden
    >
      <defs>
        <clipPath id="map-land-clip">
          <path d={LAND_PATH} />
        </clipPath>
        <clipPath id="map-reveal-clip">
          <rect x="218" y="100" width={1484 * reveal} height="474" />
        </clipPath>
        <linearGradient id="map-fill" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#0df6ff" stopOpacity=".19" />
          <stop offset=".52" stopColor="#00bdd4" stopOpacity=".095" />
          <stop offset="1" stopColor="#006676" stopOpacity=".035" />
        </linearGradient>
        <linearGradient id="map-edge" x1="240" y1="0" x2="1680" y2="0">
          <stop offset="0" stopColor="#0099ae" stopOpacity=".35" />
          <stop offset=".5" stopColor="#67f8ff" stopOpacity=".95" />
          <stop offset="1" stopColor="#0099ae" stopOpacity=".35" />
        </linearGradient>
        <pattern
          id="map-dots"
          width="16"
          height="16"
          patternUnits="userSpaceOnUse"
        >
          <circle cx="2.2" cy="2.2" r="1.45" fill="#13e8f3" opacity=".68" />
        </pattern>
        <filter id="map-glow" x="-20%" y="-30%" width="140%" height="160%">
          <feGaussianBlur stdDeviation="5.5" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      <g clipPath="url(#map-reveal-clip)">
        <path d={LAND_PATH} fill="#011b21" opacity=".92" />
        <path d={LAND_PATH} fill="url(#map-fill)" />
        <rect
          x="210"
          y="98"
          width="1500"
          height="610"
          fill="url(#map-dots)"
          clipPath="url(#map-land-clip)"
          opacity={0.42 + breathing * 0.18}
        />
        <path
          d={LAND_PATH}
          fill="none"
          stroke="url(#map-edge)"
          strokeWidth="2.15"
          strokeLinejoin="round"
          filter="url(#map-glow)"
          opacity=".88"
        />
        <path
          d={BORDER_PATH}
          fill="none"
          stroke="#43e9f1"
          strokeWidth=".72"
          strokeLinecap="round"
          opacity=".34"
        />

        <rect
          x={scanX - 48}
          y="110"
          width="96"
          height="458"
          fill="url(#map-scan-gradient)"
          clipPath="url(#map-land-clip)"
          opacity=".68"
        />
        <line
          x1={scanX}
          x2={scanX}
          y1="120"
          y2="568"
          stroke="#a9fdff"
          strokeWidth="1.2"
          clipPath="url(#map-land-clip)"
          opacity={0.44 + breathing * 0.2}
          filter="url(#cyan-glow)"
        />
      </g>
      <defs>
        <linearGradient id="map-scan-gradient" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#64faff" stopOpacity="0" />
          <stop offset=".5" stopColor="#64faff" stopOpacity=".38" />
          <stop offset="1" stopColor="#64faff" stopOpacity="0" />
        </linearGradient>
      </defs>
    </svg>
  );
};

const DeclineChart: React.FC<{
  frame: number;
  visibility: number;
  reveal: number;
}> = ({frame, visibility, reveal}) => {
  const corePulse = 0.86 + Math.sin(frame / 12) * 0.14;
  const endpoint = CHART_POINTS[CHART_POINTS.length - 1];
  const endIn = progress(reveal, 0.94, 1, easeOut);

  return (
    <svg
      width="1920"
      height="1080"
      viewBox="0 0 1920 1080"
      style={{position: "absolute", inset: 0, opacity: visibility}}
      aria-hidden
    >
      <defs>
        <linearGradient id="red-area" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#ff193f" stopOpacity=".48" />
          <stop offset=".45" stopColor="#b70022" stopOpacity=".25" />
          <stop offset="1" stopColor="#32000b" stopOpacity=".045" />
        </linearGradient>
        <pattern
          id="red-hatch"
          width="14"
          height="14"
          patternUnits="userSpaceOnUse"
          patternTransform="rotate(28)"
        >
          <line
            x1="0"
            y1="0"
            x2="0"
            y2="14"
            stroke="#ff4967"
            strokeWidth="2"
            opacity=".16"
          />
        </pattern>
        <clipPath id="chart-reveal">
          <rect x="270" y="500" width={1352 * reveal} height="520" />
        </clipPath>
        <filter id="red-line-glow" x="-20%" y="-30%" width="140%" height="160%">
          <feGaussianBlur stdDeviation="10" result="wide" />
          <feGaussianBlur in="SourceGraphic" stdDeviation="2.6" result="near" />
          <feMerge>
            <feMergeNode in="wide" />
            <feMergeNode in="near" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      <g clipPath="url(#chart-reveal)">
        <path d={CHART_AREA} fill="url(#red-area)" />
        <path d={CHART_AREA} fill="url(#red-hatch)" />
        <path
          d={CHART_LINE}
          fill="none"
          stroke="#ff153c"
          strokeWidth="13"
          strokeLinejoin="round"
          strokeLinecap="round"
          opacity=".62"
          filter="url(#red-line-glow)"
        />
        <path
          d={CHART_LINE}
          pathLength={1}
          fill="none"
          stroke="#ff3154"
          strokeWidth="6.5"
          strokeLinejoin="round"
          strokeLinecap="round"
          strokeDasharray={1}
          strokeDashoffset={1 - reveal}
          filter="url(#red-line-glow)"
        />
        <path
          d={CHART_LINE}
          pathLength={1}
          fill="none"
          stroke="#fff4f6"
          strokeWidth="2.2"
          strokeLinejoin="round"
          strokeLinecap="round"
          strokeDasharray={1}
          strokeDashoffset={1 - reveal}
          opacity={corePulse}
        />
      </g>

      <g
        transform={`translate(${endpoint[0]} ${endpoint[1]}) scale(${endIn})`}
        opacity={endIn}
        filter="url(#red-line-glow)"
      >
        <circle r={21 + Math.sin(frame / 9) * 3} fill="#ff153c" opacity=".19" />
        <circle r="8.5" fill="#fff7f8" />
        <circle r="4.5" fill="#ff2046" />
      </g>

      <path
        d={`${CHART_LINE} L1594,1030`}
        fill="none"
        stroke="#ff3352"
        strokeWidth="1"
        opacity=".13"
        transform="translate(0 28) scale(1 .22)"
        style={{transformOrigin: "960px 1000px"}}
        filter="blur(4px)"
      />
    </svg>
  );
};

export const Motion: React.FC = () => {
  const frame = useCurrentFrame();

  const globalIn = progress(frame, 0, 52, easeOut);
  const globalOut = 1 - progress(frame, 832, 899, easeInOut);
  const globalVisibility = globalIn * globalOut;

  const mapReveal = progress(frame, 34, 166, easeOut);
  const mapOut = 1 - progress(frame, 766, 858, easeInOut);
  const mapVisibility = globalVisibility * mapOut;

  const chartRevealIn = progress(frame, 118, 526, easeInOut);
  const chartOut = 1 - progress(frame, 742, 842, easeInOut);
  const chartReveal = chartRevealIn * chartOut;
  const chartVisibility = globalVisibility;

  const pushIn =
    progress(frame, 404, 548, easeInOut) *
    (1 - progress(frame, 678, 770, easeInOut));
  const cameraScale = 1 + pushIn * 0.028;
  const cameraX = pushIn * -14;
  const cameraY = pushIn * -9;

  const hudOpacity =
    progress(frame, 14, 84, easeOut) *
    (1 - progress(frame, 790, 876, easeInOut));

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#010507",
        overflow: "hidden",
      }}
    >
      <Atmosphere frame={frame} intensity={globalVisibility} />

      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `translate(${cameraX}px, ${cameraY}px) scale(${cameraScale})`,
          transformOrigin: "55% 60%",
        }}
      >
        <svg
          width="1920"
          height="1080"
          style={{position: "absolute", inset: 0, pointerEvents: "none"}}
          aria-hidden
        >
          <defs>
            <filter id="cyan-glow" x="-100%" y="-100%" width="300%" height="300%">
              <feGaussianBlur stdDeviation="4" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
            <filter
              id="red-soft-glow"
              x="-100%"
              y="-100%"
              width="300%"
              height="300%"
            >
              <feGaussianBlur stdDeviation="5" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>
        </svg>

        <RealWorldMap
          frame={frame}
          visibility={mapVisibility}
          reveal={mapReveal}
        />

        <svg
          width="1920"
          height="1080"
          viewBox="0 0 1920 1080"
          style={{position: "absolute", inset: 0}}
          aria-hidden
        >
          {RISK_NODES.map((node, index) => (
            <RiskNode
              key={`${node.x}-${node.y}`}
              {...node}
              index={index}
              frame={frame}
              mapVisibility={mapVisibility}
            />
          ))}
        </svg>

        <DeclineChart
          frame={frame}
          visibility={chartVisibility}
          reveal={chartReveal}
        />
      </div>

      <svg
        width="1920"
        height="1080"
        viewBox="0 0 1920 1080"
        style={{position: "absolute", inset: 0}}
        aria-hidden
      >
        <defs>
          <filter id="cyan-glow" x="-100%" y="-100%" width="300%" height="300%">
            <feGaussianBlur stdDeviation="4" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        <CornerBracket x={72} y={84} opacity={hudOpacity} />
        <CornerBracket x={1848} y={84} flipX opacity={hudOpacity} />
        <CornerBracket x={72} y={996} flipY opacity={hudOpacity} />
        <CornerBracket x={1848} y={996} flipX flipY opacity={hudOpacity} />

        <g opacity={hudOpacity * 0.72}>
          {[0, 1, 2, 3, 4].map((index) => (
            <rect
              key={index}
              x={1590 + index * 26}
              y={104 + (4 - index) * 7}
              width="13"
              height={20 + index * 7}
              rx="2"
              fill={index < 3 ? "#00c6dc" : "#ff244b"}
              opacity={0.42 + index * 0.12}
              filter={index >= 3 ? "url(#red-soft-glow)" : "url(#cyan-glow)"}
            />
          ))}
        </g>

        <g
          transform="translate(114 150)"
          opacity={hudOpacity * (0.72 + Math.sin(frame / 18) * 0.18)}
        >
          <circle r="38" fill="none" stroke="#00c8de" strokeWidth="2" />
          <circle
            r="27"
            fill="none"
            stroke="#49f2fa"
            strokeWidth="1"
            strokeDasharray="12 8"
            transform={`rotate(${frame * 0.32})`}
          />
          <circle r="8" fill="#00d7e9" opacity=".35" />
          <circle r="3" fill="#b9fdff" />
        </g>
      </svg>

      <div
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
          opacity: 0.25,
          background:
            "linear-gradient(90deg,rgba(255,255,255,.025),transparent 2%,transparent 98%,rgba(255,255,255,.02)),linear-gradient(180deg,rgba(255,255,255,.018),transparent 2%,transparent 98%,rgba(255,255,255,.02))",
        }}
      />
    </AbsoluteFill>
  );
};
